                case 0:
                    ReadVarint(data, ref offset);
                    break;
                case 1:
                    offset += 8;
                    break;
                case 2:
                {
                    uint length = ReadVarint(data, ref offset);
                    if (offset + (long)length > data.Length)
                    {
                        throw new InvalidDataException("Invalid event: truncated payload.");
                    }

                    if (groupDepth == 0)
                    {

                        if (field == 1)
                        {
                            // A duplicate of a singular message-typed field
                            // merges here and replaces in ts-proto; reject.
                            ulong bit = 1UL << (int)field;
                            if ((seenSingular & bit) != 0)
                            {
                                throw new InvalidDataException(
                                    "Invalid event: duplicate singular field.");
                            }

                            seenSingular |= bit;
                        }
                        switch (field)
                        {
                            case 1:
                                ScanBaseEvent(data.Slice(offset, (int)length));
                                break;
                        }
                    }

                    offset += (int)length;
                    break;
                }
                case 5:
                    offset += 4;
                    break;
                default:
                    throw new InvalidDataException("Invalid event: unknown wire type.");
            }

            if (offset > data.Length)
            {
                throw new InvalidDataException("Invalid event: truncated payload.");
            }
        }

        if (groupDepth != 0)
        {
            throw new InvalidDataException("Invalid event: unbalanced group.");
        }
    }

    private static void ScanReasoningEncryptedValueEvent(ReadOnlySpan<byte> data)
    {
        int offset = 0;
        int groupDepth = 0;
        ulong seenSingular = 0;

        while (offset < data.Length)
        {
            uint tag = ReadVarint(data, ref offset);
            uint field = tag / 8;
            uint wireType = tag % 8;

            if (field == 0)
            {
                throw new InvalidDataException("Invalid event: field zero is not a legal tag.");
            }

            if (wireType == 3)
            {
                groupDepth += 1;
                continue;
            }

            if (wireType == 4)
            {
                groupDepth -= 1;
                if (groupDepth < 0)
                {
                    throw new InvalidDataException("Invalid event: unbalanced group.");
                }

                continue;
            }

            switch (wireType)
            {
                case 0:
                    ReadVarint(data, ref offset);
                    break;
                case 1:
                    offset += 8;
                    break;
                case 2:
                {
                    uint length = ReadVarint(data, ref offset);
                    if (offset + (long)length > data.Length)
                    {
                        throw new InvalidDataException("Invalid event: truncated payload.");
                    }

                    if (groupDepth == 0)
                    {

                        if (field == 1)
                        {
                            // A duplicate of a singular message-typed field
                            // merges here and replaces in ts-proto; reject.
                            ulong bit = 1UL << (int)field;
                            if ((seenSingular & bit) != 0)
                            {
                                throw new InvalidDataException(
                                    "Invalid event: duplicate singular field.");
                            }

                            seenSingular |= bit;
                        }
                        switch (field)
                        {
                            case 1:
                                ScanBaseEvent(data.Slice(offset, (int)length));
                                break;
                        }
                    }

                    offset += (int)length;
                    break;
                }
                case 5:
                    offset += 4;
                    break;
                default:
                    throw new InvalidDataException("Invalid event: unknown wire type.");
            }

            if (offset > data.Length)
            {
                throw new InvalidDataException("Invalid event: truncated payload.");
            }
        }

        if (groupDepth != 0)
        {
            throw new InvalidDataException("Invalid event: unbalanced group.");
        }
    }

    // Mirrors the uint32 reader truncation exactly: the fifth byte contributes
    // only its low four bits, later bytes none — otherwise an overlong tag
    // encoding would dodge duplicate detection while the real decoder still
    // reads the canonical field number.
    private static uint ReadVarint(ReadOnlySpan<byte> data, ref int offset)
    {
        uint result = 0;
        int shift = 0;
        while (true)
        {
            if (offset >= data.Length)
            {
                throw new InvalidDataException("Invalid event: truncated varint.");
            }

            byte value = data[offset++];
            if (shift < 28)
            {
                result += (uint)(value & 0x7f) << shift;
            }
            else if (shift == 28)
            {
                result += (uint)(value & 0x0f) << 28;
            }

            shift += 7;
            if ((value & 0x80) == 0)
            {
                return result;
            }
        }
    }
}
